-- Impano — base MySQL (structure + données). Source : données en ligne de votre site.
-- Import : phpMyAdmin → votre base → Importer → ce fichier.
-- Les comptes (dont l'administrateur) et les commandes sont créés / importés par le site lui-même.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(120), phone VARCHAR(40), pass VARCHAR(255) NOT NULL, is_admin TINYINT NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS categories(rid INT AUTO_INCREMENT PRIMARY KEY, pos INT NOT NULL DEFAULT 0, id VARCHAR(80) NOT NULL, label VARCHAR(200), short VARCHAR(120), img VARCHAR(600), blurb TEXT, extra LONGTEXT, KEY ix_cid(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS products(rid INT AUTO_INCREMENT PRIMARY KEY, pos INT NOT NULL DEFAULT 0, id VARCHAR(120) NOT NULL, cat VARCHAR(80), name VARCHAR(240), price DECIMAL(10,2), img VARCHAR(600), gallery LONGTEXT, tag VARCHAR(120), color VARCHAR(200), descr TEXT, details LONGTEXT, sizes LONGTEXT, stock INT NULL, hidden TINYINT NOT NULL DEFAULT 0, added BIGINT NULL, extra LONGTEXT, KEY ix_pid(id), KEY ix_pcat(cat)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS content(k VARCHAR(190) PRIMARY KEY, v LONGTEXT, is_json TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS config(k VARCHAR(120) PRIMARY KEY, v LONGTEXT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS meta(k VARCHAR(60) PRIMARY KEY, updated_at VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY, ref VARCHAR(40) NOT NULL UNIQUE, created_at VARCHAR(40) NOT NULL, user_id INT NULL, client LONGTEXT NOT NULL, items LONGTEXT NOT NULL, total DECIMAL(12,2) NOT NULL, shipping DECIMAL(10,2), delivery VARCHAR(60), payment VARCHAR(60), note TEXT, status VARCHAR(20) NOT NULL DEFAULT 'nouveau', ip VARCHAR(60), KEY ix_orders_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS attempts(k VARCHAR(190) NOT NULL, t INT NOT NULL, KEY ix_att(k,t)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM categories;
DELETE FROM products;
DELETE FROM content;
DELETE FROM config;
DELETE FROM meta;


SET FOREIGN_KEY_CHECKS=1;
